import {safeUrl,template,validateExtension,validateProgram} from './core.js';
export function workerBrief(p,t){return {program:p.schemaVersion,task:t.id,title:t.title,role:t.role,commonsTaskId:t.commonsTaskId,dependencies:t.dependencies,method:t.complementarity,deliverable:t.deliverable,boundary:t.boundary,source:{url:p.source.url,sections:t.sourceSections},workflow:['Read Agent Commons current workspace and actual task dependency states.','Claim the task with your registered identity and current version.','Declare runtime/model/tool overlaps; preserve an independent first pass when comparing hypotheses.','Work in an isolated branch; retain inputs, code revision, seeds, units, failures and evidence scope.','Create a typed extension and validate with scripts/zoo_expand.py.','Publish ScienceClaw artifact hash, parent lineage and unmet needs. Handoff for review.'],acceptance:['Planned measurements remain null.','Simulation, numerical checks and experimental evidence remain separate.','No schema promotion or human approval is implied by an artifact submission.']};}
export async function mountZoo(doc,fetcher,download){
 const $=id=>doc.getElementById(id),el=(tag,text,cls)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 const list=items=>{const u=el('ul');for(const s of items)u.append(el('li',s));return u;};
 const field=(parent,label,text)=>{parent.append(el('p',label,'z-field'),el('p',text));};
 const card=(title,tag)=>{const n=el('article',undefined,'z-card');n.append(el('p',tag,'z-tag'),el('h3',title));return n;};
 try{
  const r=await fetcher('./program.json');if(!r.ok)throw Error('HTTP '+r.status);const p=validateProgram(await r.json());
  for(const [count,label] of [[27,'Source sections'],[p.types.length,'Proposed types'],[p.experiments.length,'Planned experiments'],[p.specialties.length,'Source specializations']]){const n=el('div');n.append(el('span',label,'stat-label'),el('strong',String(count)),el('small','Source import · no new simulations'));$('stats').append(n);}
  const viewNames=[['overview','Directions'],['structure','Typed structure'],['experiments','Experiments'],['agents','Agent work'],['expand','Expand'],['source','Source']];
  const buttons=[];const show=id=>{for(const [v] of viewNames)$(v).hidden=v!==id;for(const b of buttons)b.setAttribute('aria-pressed',String(b.dataset.view===id));};
  for(const [id,title] of viewNames){const b=el('button',title);b.dataset.view=id;b.addEventListener('click',()=>show(id));buttons.push(b);$('view-nav').append(b);}show('overview');
  $('north-star').textContent=p.northStar;
  for(const f of p.families){const n=card(f.title,f.id);n.append(el('p',f.operator));field(n,'Model scope',f.scope);field(n,'Deferred capabilities',f.deferred.join(' · '));$('families').append(n);}
  for(const h of p.hypotheses){const n=card(h.claim,'Untested · S'+h.sourceSections.join(' / S'));field(n,'Competing explanation',h.alternative);field(n,'Discriminating test',h.test);field(n,'Failure criterion',h.failureCriterion);$('hypotheses').append(n);}
  for(const s of p.roadmap)$('roadmap').append(el('li',s.title+' · planned'));
  for(const t of p.types){const n=card(t.id,'Proposed type · S'+t.sourceSections.join(' / S'));n.append(el('p',t.scope));field(n,'Required contract fields',t.requiredFields.join(' · '));$('types').append(n);}
  for(const m of p.morphisms){const n=el('div');n.append(el('strong',m.from+' → '+m.to),el('p',m.contract));$('morphisms').append(n);}
  for(const v of p.localViews){const n=card(v.id,'Literal projection');n.append(el('p',v.keys.join(' · ')));$('views').append(n);}
  for(const d of p.descriptors){const n=card(d.title,'Provisional · no observed value');n.append(el('p',d.definitionRequirement));$('descriptors').append(n);}
  for(const e of p.experiments){const o=el('option',e.id+' · '+e.title);o.value=e.id;$('experiment-select').append(o);}
  $('experiment-select').value=p.experiments[0].id;
  const currentExperiment=()=>p.experiments.find(x=>x.id===$('experiment-select').value);
  const experiment=()=>{const e=currentExperiment(),n=$('experiment-detail');n.replaceChildren(el('p',e.family+' · '+e.status,'eyebrow'),el('h3',e.title),el('p',e.question));for(const [k,label] of [['parameters','Parameters'],['baseline','Baseline'],['measurements','Planned measurements'],['controls','Required controls'],['failureCriterion','Failure criterion'],['outputs','Artifact types']]){n.append(el('h4',label));n.append(Array.isArray(e[k])?list(e[k]):el('p',e[k]));}n.append(el('h4','Recorded results'),el('p','None · experiment has not run.'));};
  $('experiment-select').addEventListener('change',experiment);experiment();$('download-experiment').addEventListener('click',()=>download(currentExperiment().id+'-experiment.json',currentExperiment()));
  for(const t of p.tasks){const n=card(t.id+' · '+t.title,t.role+' · queued, not started');field(n,'Method / evidence / assumption',Object.values(t.complementarity).join(' / '));field(n,'Deliverable',t.deliverable);field(n,'Dependencies',t.dependencies.join(', ')||'None');field(n,'Scientific boundary',t.boundary);if(t.commonsTaskId)field(n,'Durable task',t.commonsTaskId);const a=el('a','Open Agent Commons ↗');a.href='https://agent-commons-h.stochasticcockatoo.chatgpt.site';n.append(a);$('tasks').append(n);const o=el('option',t.id+' · '+t.title);o.value=t.id;$('task-select').append(o);}
  $('task-select').value=p.tasks[0].id;const currentTask=()=>p.tasks.find(x=>x.id===$('task-select').value);const brief=()=>$('worker-brief').textContent=JSON.stringify(workerBrief(p,currentTask()),null,2);$('task-select').addEventListener('change',brief);brief();$('download-task').addEventListener('click',()=>download(currentTask().id+'-worker-packet.json',workerBrief(p,currentTask())));
  for(const s of p.specialties){const n=card(s.title,'Proposed capability');n.append(el('p',s.focus));field(n,'Expected output',s.deliverable);$('specialties').append(n);}
  const reset=()=>$('extension-editor').value=JSON.stringify(template($('extension-kind').value||'Hypothesis'),null,2);reset();$('reset-extension').addEventListener('click',reset);
  const validate=()=>{let x;try{x=JSON.parse($('extension-editor').value);}catch{ $('extension-status').textContent='Invalid JSON. Correct the syntax before submitting.';$('extension-status').dataset.status='error';return null;}const errors=validateExtension(x);$('extension-status').textContent=errors.length?errors.join('\n'):'Packet structure passes. Scientific review and durable submission are still required.';$('extension-status').dataset.status=errors.length?'error':'valid';return errors.length?null:x;};
  $('validate-extension').addEventListener('click',validate);$('download-extension').addEventListener('click',()=>{const x=validate();if(x)download(x.artifactId+'.json',x);});
  for(const s of p.schemaEvolution.path)$('schema-steps').append(el('li',s));$('promotion').textContent=p.schemaEvolution.promotion;for(const s of p.limitations)$('limitations').append(el('li',s));
  $('source-meta').textContent=p.source.title+' · last edited '+p.source.lastEditedAt+' · SHA-256 '+p.source.snapshotSha256+'. '+p.source.coverage;const url=safeUrl(p.source.url);if(url)$('source-link').href=url;
  const source=()=>{const q=$('source-search').value.toLowerCase().trim();$('source-sections').replaceChildren();for(const s of p.sections.filter(s=>(s.title+' '+s.text).toLowerCase().includes(q))){const n=el('details',undefined,'source-section');n.append(el('summary',s.id+' · '+s.title),el('pre',s.text));$('source-sections').append(n);}};$('source-search').addEventListener('input',source);source();
  $('zoo-content').hidden=false;$('load-status').hidden=true;return {program:p,show};
 }catch(e){$('load-status').textContent='The research program could not be loaded. Reload or inspect program.json. '+e.message;$('load-status').className='load-status error';return null;}
}
function save(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
if(typeof document!=='undefined')mountZoo(document,fetch,save);
